// 4-bit shift register, positive edge triggered register reset (areset),
// synchronous load (load) and enable (ena).
module TopModule(
    input  clk,
    input  areset,
    input  load,
    input  ena,
    input  [3:0] data,
    output reg [3:0] q
);
    reg [3:0] reg0;
    reg [3:0] reg1;
    reg [3:0] reg2;
    reg [3:0] reg3;
    wire [3:0] next_reg0;
    wire [3:0] next_reg1;
    wire [3:0] next_reg2;
    wire [3:0] next_reg3;
    always @(*) begin
        next_reg0 = load ? data : reg0;
        next_reg1 = load ? reg0 : reg1;
        next_reg2 = load ? reg1 : reg2;
        next_reg3 = load ? reg2 : reg3;
    end
    always @(posedge clk) begin
        if (areset) begin
            reg0 <= 4'd0;
            reg1 <= 4'd0;
            reg2 <= 4'd0;
            reg3 <= 4'd0;
        end else begin
            reg0 <= next_reg0;
            reg1 <= next_reg1;
            reg2 <= next_reg2;
            reg3 <= next_reg3;
        end
    end
    always @(*) begin
        if (load) q = data;
        else if (ena) q = {reg3, 1'b0, reg1, reg0};
        else q = {reg3, reg2, reg1, reg0};
    end
endmodule

